-- Marketplace, social/content, and catalog tables retained by the current DB.
BEGIN;
CREATE TABLE IF NOT EXISTS travel_groups (id serial PRIMARY KEY, country_code varchar NOT NULL UNIQUE, country_name varchar NOT NULL, name varchar NOT NULL, photo_url varchar NOT NULL, visibility varchar NOT NULL DEFAULT 'public', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS travel_group_memberships (group_id integer NOT NULL REFERENCES travel_groups(id) ON DELETE CASCADE, user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS travel_group_posts (id varchar PRIMARY KEY, group_id integer NOT NULL REFERENCES travel_groups(id) ON DELETE CASCADE, author_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_posts (id varchar PRIMARY KEY, user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE, caption text NOT NULL, media_url varchar NOT NULL, location_name varchar NOT NULL CHECK(length(btrim(location_name)) > 0), created_at timestamptz NOT NULL DEFAULT now(), content_type varchar NOT NULL DEFAULT 'post' CHECK(content_type IN ('post','reel')));
CREATE TABLE IF NOT EXISTS user_visited_places (id varchar PRIMARY KEY, user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE, visited_at date NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now(), entity_id text NOT NULL REFERENCES knowledge_entities(id) ON DELETE RESTRICT, UNIQUE(user_id,entity_id));
CREATE TABLE IF NOT EXISTS reviews (id varchar PRIMARY KEY, author_name varchar, rating integer CHECK(rating IS NULL OR rating BETWEEN 1 AND 5), published_at timestamptz, when_text varchar, language varchar, review_text text, created_at timestamptz NOT NULL DEFAULT now(), entity_id text NOT NULL REFERENCES knowledge_entities(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS festivals (id varchar PRIMARY KEY, source_id varchar NOT NULL UNIQUE, source_url varchar, name varchar NOT NULL, venue varchar, scale_level varchar NOT NULL DEFAULT 'dia-phuong', timing varchar, province varchar, district varchar, deity text, ceremony_part text, festival_part text, festival_type varchar, documentation text, protection_measure text, registration_time varchar, recurrence varchar, listed_year integer, metadata json NOT NULL DEFAULT '{}'::json, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS marketplace_plans (id varchar PRIMARY KEY, creator_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE, status varchar NOT NULL DEFAULT 'draft', current_published_version_id varchar, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS marketplace_plan_versions (id varchar PRIMARY KEY, marketplace_plan_id varchar NOT NULL REFERENCES marketplace_plans(id) ON DELETE CASCADE, version integer NOT NULL, source_plan_id varchar NOT NULL, source_plan_version_id varchar NOT NULL, title varchar NOT NULL, description text NOT NULL, destination varchar NOT NULL, duration_days integer NOT NULL, category varchar NOT NULL, price_amount integer NOT NULL, price_currency varchar NOT NULL DEFAULT 'VND', media_urls json NOT NULL DEFAULT '[]'::json, preview_snapshot json NOT NULL DEFAULT '{}'::json, moderation_status varchar NOT NULL DEFAULT 'draft', rejection_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, UNIQUE(marketplace_plan_id,version));
CREATE TABLE IF NOT EXISTS favorites (user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE, marketplace_plan_id varchar NOT NULL REFERENCES marketplace_plans(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,marketplace_plan_id));
CREATE TABLE IF NOT EXISTS orders (id varchar PRIMARY KEY, buyer_id integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, total_amount integer NOT NULL, currency varchar NOT NULL DEFAULT 'VND', status varchar NOT NULL DEFAULT 'pending', idempotency_key varchar UNIQUE, provider_request_id varchar UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz, refunded_at timestamptz);
CREATE TABLE IF NOT EXISTS order_items (id varchar PRIMARY KEY, order_id varchar NOT NULL REFERENCES orders(id) ON DELETE CASCADE, marketplace_plan_id varchar NOT NULL REFERENCES marketplace_plans(id) ON DELETE RESTRICT, marketplace_plan_version_id varchar NOT NULL REFERENCES marketplace_plan_versions(id) ON DELETE RESTRICT, unit_amount integer NOT NULL, currency varchar NOT NULL DEFAULT 'VND', quantity integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS payments (id varchar PRIMARY KEY, order_id varchar NOT NULL REFERENCES orders(id) ON DELETE CASCADE, provider varchar NOT NULL, method varchar NOT NULL, request_id varchar UNIQUE, transaction_id varchar UNIQUE, amount integer NOT NULL, currency varchar NOT NULL DEFAULT 'VND', status varchar NOT NULL DEFAULT 'pending', payment_url text, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_events (id varchar PRIMARY KEY, payment_id varchar REFERENCES payments(id) ON DELETE SET NULL, order_id varchar REFERENCES orders(id) ON DELETE SET NULL, provider varchar NOT NULL, provider_event_id varchar NOT NULL, request_id varchar, transaction_id varchar, event_type varchar NOT NULL, payload json NOT NULL DEFAULT '{}'::json, received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_event_id));
CREATE TABLE IF NOT EXISTS entitlements (id varchar PRIMARY KEY, user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE, order_id varchar NOT NULL REFERENCES orders(id) ON DELETE CASCADE, order_item_id varchar NOT NULL UNIQUE REFERENCES order_items(id) ON DELETE CASCADE, marketplace_plan_id varchar NOT NULL REFERENCES marketplace_plans(id) ON DELETE RESTRICT, marketplace_plan_version_id varchar NOT NULL REFERENCES marketplace_plan_versions(id) ON DELETE RESTRICT, status varchar NOT NULL DEFAULT 'active', copied_plan_id varchar, copied_plan_version_id varchar, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS marketplace_reviews (id varchar PRIMARY KEY, reviewer_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE, marketplace_plan_id varchar NOT NULL REFERENCES marketplace_plans(id) ON DELETE CASCADE, marketplace_plan_version_id varchar REFERENCES marketplace_plan_versions(id) ON DELETE SET NULL, order_id varchar REFERENCES orders(id) ON DELETE SET NULL, rating integer NOT NULL, comment text NOT NULL, status varchar NOT NULL DEFAULT 'published', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(reviewer_id,marketplace_plan_id));
CREATE TABLE IF NOT EXISTS reports (id varchar PRIMARY KEY, reporter_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE, marketplace_plan_id varchar NOT NULL REFERENCES marketplace_plans(id) ON DELETE CASCADE, marketplace_plan_version_id varchar REFERENCES marketplace_plan_versions(id) ON DELETE SET NULL, reason varchar NOT NULL, description text NOT NULL, status varchar NOT NULL DEFAULT 'pending', resolution text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
COMMIT;
